for k,c in C.items():
    tn,g=k.split('|'); p=c['pred']; P(f"| {tn} {'2' if g=='2' else '0.5'} % | {c['hw_costs']} | {c['hw_cost']:.1f} | " + " | ".join(f"{p[v]['alloc_vm']:.1f} | {p[v]['err_pct']:+.2f}" for v in 'abcd') + f" | {c['s4_hw_cost']:.1f} |")
r=E['t8_ratio']
P(f"\n**Secondary, t8 cost ratio S4′ / S4 (hardware)**: 2 % {r['hw']['2']:.4f} ({100*(r['hw']['2']-1):+.2f} %), 0.5 % {r['hw']['05']:.4f} ({100*(r['hw']['05']-1):+.2f} %). Predicted: (a)(c) +0.84 % / +1.02 %, (b) +2.21 % / +1.68 %. Hardware has S4′ slightly cheaper, predictions slightly costlier; the S4 reference has only two runs per point and the S4′ t8 2 % runs spread 1007–1078, so the sign of a ≤ 1 % ratio is not resolved by n = 3 vs 2 [已驗證 numbers; 推測 on resolution].\n")
